#!/usr/bin/env bash
# Generated by gq (@getquick/site) from gq.ops.json; gq sync rewrites it.
#
# Request admission for a Site that guards Composer packages. While a deploy
# holds the Site, every PHP request PHP-FPM runs for its web root is answered
# 503 before any other PHP code runs: WordPress, its installer and upgrader,
# setup-config, a plugin's own PHP file. Command-line PHP (WP-CLI: the deploy
# and a recovery) is never held. Static files aren't PHP: nginx still serves
# them.
#
# The gate is enforced by the server, not by a file a package could
# override: the PHP-FPM pool serving the admin domain must already prepend
# it with
#
#   php_admin_value[auto_prepend_file] = $SITE_PATH/.gq/admission.php
#
# which neither a .user.ini (of any user_ini.filename) nor php_value nor
# ini_set can change. gq never configures PHP-FPM or nginx; without that
# setting every guarded deploy refuses. See @getquick/site's
# docs/reference/package-expectations.md for the whole hosting contract
# (among it: nginx routes every PHP script under the web root to that one
# pool).
#
#   SITE_PATH=… APP_PATH=apps/cms admission.sh prepare  # install the gate
#   SITE_PATH=… APP_PATH=apps/cms admission.sh begin    # hold, and prove it
#   SITE_PATH=… APP_PATH=apps/cms admission.sh lift     # open (a deploy's end)
#
# What it owns, all outside what Composer or the release's rsync write:
#   $SITE_PATH/.gq/admission.php    the gate (rewritten only when it differs)
#   $SITE_PATH/.gq/state            the admission state: the Site is served
#                                   only while the gate reads exactly
#                                   "open"; "held <nonce>" (the nonce is
#                                   public freshness evidence, no secret),
#                                   no file, a file it can't read (an
#                                   open_basedir that excludes it
#                                   included), a symlink or anything else
#                                   is held
#   $SITE_PATH/$APP_PATH/web/gq-admission/<attempt>/
#                                   one attempt's challenge: probe.php and
#                                   per-directory INI files that try to turn
#                                   the prepend off; removed by that attempt
#                                   (left by a killed one), never by another
#
# `begin`, before any package file changes:
#   1. installs the gate if it differs;
#   2. requests a fresh challenge's probe.php over TLS for the admin domain
#      on this machine: the gate must answer it (the nested override didn't
#      win), reporting PHP_VERSION, its worker's pid and user_ini.filename (a
#      custom one is challenged too, in another fresh directory, so no
#      worker's INI cache hides it). The worker must be a worker of PHP-FPM
#      <version>'s master; its pool is the pool serving the Site;
#   3. writes the state "held <nonce>", reloads PHP-FPM <version> (which
#      must succeed) and
#      waits, at most 120 seconds, until no worker of that master that ran
#      before the reload still runs, so no request that started before the
#      hold still runs WordPress code;
#   4. requires 4 more probes to answer 503 with this hold's nonce, each from
#      a worker of the same pool started after the reload.
# Anything it can't prove fails before any package file changes. A known
# failure removes its own challenges and puts the state back to "open" only
# if the Site was open before and the state is still this attempt's hold
# (the Site's code is the previous, verified one); a Site that was held
# stays held. Any other exit of `begin` (an unexpected error) removes only
# its own temporary and challenge files and never opens the Site; a killed
# `begin` (SIGKILL) can leave its hold and challenge directory before any
# package changed. `lift` is the only other way to "open": the end of a
# deploy that verified and finished every step.
# The probes sample the workers serving one URL: they prove the pool's
# setting, not how nginx routes every other script (the hosting contract).
set -euo pipefail

# gq.ops.json's domains.admin, if it is a plain hostname; empty otherwise.
ADMIN_HOST="{{domains.adminHost}}"
SITE_PATH="${SITE_PATH:-}"
APP_PATH="${APP_PATH:-apps/cms}"
# How long workers that ran before the hold may take to go, in seconds: at
# most 120, which the environment may only shorten.
DRAIN_LIMIT=120
DRAIN_SECONDS="${GQ_ADMISSION_DRAIN_SECONDS:-$DRAIN_LIMIT}"
# Probes of the held Site from the reloaded pool.
HELD_PROBES=4

refuse() {
  echo "$1" >&2
  exit 1
}

case "$SITE_PATH" in
  /*) ;;
  *) refuse "admission.sh needs SITE_PATH, the Site's absolute path." ;;
esac
# Paths gq writes are plain: the web root appears in the gate's PHP source.
[[ "$SITE_PATH" =~ ^/[A-Za-z0-9._/-]+$ && "$APP_PATH" =~ ^[A-Za-z0-9._/-]+$ ]] \
  || refuse "The Site's path has characters gq won't write into the admission gate."
[[ "/$SITE_PATH/$APP_PATH/" != *"/../"* && "/$SITE_PATH/$APP_PATH/" != *"/./"* ]] \
  || refuse "The Site's path has . or .. segments."
case "$DRAIN_SECONDS" in
  '' | *[!0-9]*) refuse "GQ_ADMISSION_DRAIN_SECONDS isn't a number of seconds." ;;
esac
{ [ "$DRAIN_SECONDS" -ge 1 ] && [ "$DRAIN_SECONDS" -le "$DRAIN_LIMIT" ]; } \
  || refuse "GQ_ADMISSION_DRAIN_SECONDS must be between 1 and $DRAIN_LIMIT."

GQ_DIR="$SITE_PATH/.gq"
GATE="$GQ_DIR/admission.php"
STATE="$GQ_DIR/state"
WEB="$SITE_PATH/$APP_PATH/web"
PROBES="$WEB/gq-admission"

# A path gq manages must be absent or a regular file (a directory for the
# directories), never a symlink.
plain_file() {
  if [ -L "$1" ] || { [ -e "$1" ] && [ ! -f "$1" ]; }; then
    refuse "$1 isn't a regular file gq can manage; nothing changed."
  fi
}
plain_directory() {
  if [ -L "$1" ] || { [ -e "$1" ] && [ ! -d "$1" ]; }; then
    refuse "$1 isn't a directory gq can manage; nothing changed."
  fi
}
check_paths() {
  plain_directory "$GQ_DIR"
  plain_directory "$SITE_PATH/$APP_PATH"
  plain_directory "$WEB"
  plain_directory "$PROBES"
  plain_file "$GATE"
  plain_file "$STATE"
}

# Replaces $1 with $2's content atomically (a rename in the same directory).
# Until the rename, the temporary file is in temporaries, for cleanup.
temporaries=()
write_atomically() {
  local target="$1" temporary
  temporary="$(mktemp "$(dirname "$target")/.gq-admission.XXXXXX")"
  temporaries+=("$temporary")
  printf '%s' "$2" >"$temporary"
  chmod 0644 "$temporary"
  mv -f "$temporary" "$target"
  temporaries=("${temporaries[@]:0:${#temporaries[@]}-1}")
}

# Removes this process's own temporary files a failed write left.
remove_temporaries() {
  local temporary
  for temporary in "${temporaries[@]}"; do
    if [ -f "$temporary" ] && [ ! -L "$temporary" ]; then rm -f "$temporary"; fi
  done
  temporaries=()
}

# Whether the state file says exactly "open" (a regular file, not a
# symlink, readable): every other state is held.
state_is_open() {
  [ -f "$STATE" ] && [ ! -L "$STATE" ] && [ -r "$STATE" ] \
    && [ "$(head -c 80 "$STATE" 2>/dev/null | od -An -tx1 | tr -d ' \n')" = "6f70656e0a" ]
}

# Whether the state file is exactly "held $1".
state_is_hold() {
  [ -f "$STATE" ] && [ ! -L "$STATE" ] && [ "$(cat "$STATE" 2>/dev/null)" = "held $1" ] \
    && [ "$(wc -c <"$STATE")" = "$((${#1} + 6))" ]
}

new_nonce() {
  od -An -N16 -tx1 /dev/urandom | tr -d ' \n'
}

# The gate, for the resolved web root $1. It acts only on this Site's
# requests: another Site's (both its script and its document root resolve
# outside this web root) passes untouched; a request whose server values
# are missing or don't resolve is treated as this Site's.
gate_source() {
  cat <<GQ_GATE
<?php
// GETQUICK request admission (deploy/ploi/admission.sh). PHP-FPM's pool
// prepends this to every script (php_admin_value[auto_prepend_file]). While
// the admission state beside this file isn't exactly "open", every web
// request for its web root ends here, 503, before any other PHP code; a
// challenge probe is always answered here. Command-line PHP is never held.
if (PHP_SAPI !== 'cli' && PHP_SAPI !== 'phpdbg') {
    (static function (): void {
        \$web = '$1';
        \$resolve = static function (string \$key) {
            \$value = \$_SERVER[\$key] ?? '';
            return is_string(\$value) && \$value !== '' ? realpath(\$value) : false;
        };
        \$inside = static function (\$path) use (\$web): bool {
            return \$path === \$web || strncmp(\$path, \$web . '/', strlen(\$web) + 1) === 0;
        };
        \$script = \$resolve('SCRIPT_FILENAME');
        \$root = \$resolve('DOCUMENT_ROOT');
        if (\$script !== false && \$root !== false && !\$inside(\$script) && !\$inside(\$root)) {
            return;
        }
        // Served only on a positive read of exactly "open\n". Anything else is
        // held: no state file, one PHP can't read (permissions, or an
        // open_basedir a package's .user.ini set), a symlink, other content.
        \$state = __DIR__ . '/state';
        \$value = @is_link(\$state) ? false : @file_get_contents(\$state, false, null, 0, 80);
        \$held = \$value !== "open\n";
        \$probe = \$script !== false
            && preg_match('#^' . preg_quote(\$web, '#') . '/gq-admission/[0-9a-f]{32}/probe\.php\$#', \$script) === 1;
        if (!\$held && !\$probe) {
            return;
        }
        \$nonce = 'open';
        if (\$held) {
            \$nonce = is_string(\$value) && preg_match('/^held ([0-9a-f]{32})\n\$/', \$value, \$match) === 1
                ? \$match[1] : 'invalid';
        }
        if (!headers_sent()) {
            http_response_code(\$held ? 503 : 200);
            header('Cache-Control: no-store');
            header('Content-Type: text/plain; charset=utf-8');
            header('X-GQ-Gate: ' . \$nonce);
            if (\$held) {
                header('Retry-After: 600');
            }
            if (\$probe) {
                \$ini = (string) ini_get('user_ini.filename');
                header('X-GQ-Php: ' . PHP_VERSION);
                header('X-GQ-Pid: ' . getmypid());
                header('X-GQ-User-Ini: ' . (\$ini === '' ? '-'
                    : (preg_match('/^[A-Za-z0-9._-]{1,64}\$/', \$ini) === 1 && \$ini !== '.' && \$ini !== '..' ? \$ini : 'invalid')));
            }
        }
        echo \$held ? "This site is temporarily unavailable.\n" : "gq admission probe\n";
        exit;
    })();
}
GQ_GATE
}

# The challenge's own script: it runs only when the gate didn't, and names
# nothing of the Site.
probe_source() {
  cat <<'GQ_PROBE'
<?php
// GETQUICK request admission challenge (deploy/ploi/admission.sh): reached
// only when the pool's gate didn't run for this script.
http_response_code(200);
header('Cache-Control: no-store');
header('Content-Type: text/plain; charset=utf-8');
echo "UNGATED\n";
GQ_PROBE
}

changed=()
challenges=()
challenge_files=(.user.ini)

# Installs the gate (and the challenge directory) if it differs; it never
# writes the admission state, so a Site without one stays held.
prepare() {
  check_paths
  mkdir -p "$GQ_DIR" "$PROBES"
  local web source
  web="$(cd "$WEB" && pwd -P)"
  [[ "$web" =~ ^/[A-Za-z0-9._/-]+$ ]] \
    || refuse "The Site's web root resolves to $web, which gq won't write into the gate."
  source="$(gate_source "$web")"
  if [ ! -f "$GATE" ] || [ "$(cat "$GATE")" != "$source" ]; then
    write_atomically "$GATE" "$source"$'\n'
    changed+=("the admission gate")
  fi
}

# --- PHP-FPM ------------------------------------------------------------------

# PHP-FPM's processes (named php-fpm*, so never the command that lists them)
# as "<pid> <ppid> <name> <start time> <args>".
fpm_processes() {
  ps -e -o pid= -o ppid= -o comm= -o lstart= -o args= 2>/dev/null | awk '$3 ~ /^php-fpm/' || true
}

# The workers of PHP-FPM $1's master, as "<pid> <start time> <pool>".
fpm_workers() {
  fpm_processes | awk -v master="php-fpm: master process (/etc/php/$1/fpm/php-fpm.conf)" '
    { line[NR] = $0; ppid[NR] = $2 }
    index($0, master) { masters[$1] = 1 }
    END {
      for (i = 1; i <= NR; i++) {
        if ((ppid[i] in masters) && match(line[i], /php-fpm: pool [^ ]+/)) {
          split(line[i], f, " ")
          print f[1], f[4], f[5], f[6], f[7], f[8], substr(line[i], RSTART + 14, RLENGTH - 14)
        }
      }
    }'
}

fpm_master_visible() {
  fpm_processes | grep -qF "php-fpm: master process (/etc/php/$1/fpm/php-fpm.conf)"
}

# Which of $1's "<pid> <start time> …" lines still run, wherever they are now
# (a worker whose master went is still running).
still_running() {
  comm -12 <(printf '%s\n' "$1" | grep . | cut -d ' ' -f 1-6 | sort) \
    <(ps -e -o pid= -o lstart= 2>/dev/null | awk '{ print $1, $2, $3, $4, $5, $6 }' | sort)
}

# --- probes -------------------------------------------------------------------

# Requests challenge $1's probe.php on this machine's web server for the
# admin domain, over TLS with its certificate checked, no redirect followed,
# bounded. Sets status, gate, php, pid, user_ini and ungated; returns
# non-zero when the server didn't answer.
probe() {
  local headers body
  status="" gate="" php="" pid="" user_ini="" ungated=false
  body="$(mktemp)"
  temporaries+=("$body")
  if ! headers="$(curl --silent --show-error --output "$body" --dump-header - \
    --proto '=https' --max-redirs 0 --connect-timeout 5 --max-time 15 \
    --resolve "$ADMIN_HOST:443:127.0.0.1" "https://$ADMIN_HOST/gq-admission/$1/probe.php" 2>/dev/null)"; then
    rm -f "$body"
    return 1
  fi
  headers="$(printf '%s\n' "$headers" | tr -d '\r')"
  status="$(printf '%s\n' "$headers" | head -n 1 | awk '{ print $2 }')"
  gate="$(printf '%s\n' "$headers" | sed -n 's/^x-gq-gate: //Ip' | head -n 1)"
  php="$(printf '%s\n' "$headers" | sed -n 's/^x-gq-php: //Ip' | head -n 1)"
  pid="$(printf '%s\n' "$headers" | sed -n 's/^x-gq-pid: //Ip' | head -n 1)"
  user_ini="$(printf '%s\n' "$headers" | sed -n 's/^x-gq-user-ini: //Ip' | head -n 1)"
  if [ -z "$gate" ] && grep -qx UNGATED "$body"; then ungated=true; fi
  rm -f "$body"
  temporaries=("${temporaries[@]:0:${#temporaries[@]}-1}")
}

# A fresh challenge directory for this attempt (its name in challenge), with
# probe.php and an INI file named each of challenge_files that empties
# auto_prepend_file.
challenge() {
  local file
  challenge="$(new_nonce)"
  mkdir "$PROBES/$challenge"
  challenges+=("$challenge")
  write_atomically "$PROBES/$challenge/probe.php" "$(probe_source)"$'\n'
  for file in "${challenge_files[@]}"; do
    write_atomically "$PROBES/$challenge/$file" $'auto_prepend_file =\n'
  done
}

# Removes exactly the files this attempt's challenges hold, then their
# directories if empty.
remove_challenges() {
  local name file
  for name in "${challenges[@]}"; do
    for file in probe.php "${challenge_files[@]}"; do
      if [ -f "$PROBES/$name/$file" ] && [ ! -L "$PROBES/$name/$file" ]; then
        rm -f "$PROBES/$name/$file"
      fi
    done
    rmdir "$PROBES/$name" 2>/dev/null || true
  done
  challenges=()
}

begin() {
  [[ "$ADMIN_HOST" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$ ]] \
    || refuse "gq.ops.json domains.admin isn't a hostname the admission check can request; nothing changed."
  check_paths
  local prior_open=false version pool old left deadline attempt workers line url
  nonce=""
  failing=false
  state_is_open && prior_open=true
  prepare

  # A known failure: its challenges go. The state goes back to "open" only
  # if the Site was open before and the state is still this attempt's hold
  # (no package file has changed, so the Site's code is the previous,
  # verified one); otherwise it stays as it is.
  fail() {
    local what="nothing else" outcome
    failing=true
    remove_temporaries
    remove_challenges
    if [ -z "$nonce" ]; then
      if [ "$prior_open" = true ]; then
        outcome="The admission state is unchanged: open."
      else
        outcome="The admission state is unchanged: held."
      fi
    elif [ "$prior_open" = true ] && state_is_hold "$nonce"; then
      write_atomically "$STATE" $'open\n'
      outcome="The hold this attempt placed was lifted again: the Site was open before it."
    else
      outcome="The Site stays held."
    fi
    # Every change, as "a", "a and b" or "a, b and c".
    local count="${#changed[@]}" index
    if [ "$count" -gt 0 ]; then
      what="${changed[0]}"
      for ((index = 1; index < count; index++)); do
        if [ "$index" -eq $((count - 1)) ]; then what="$what and ${changed[index]}"; else what="$what, ${changed[index]}"; fi
      done
    fi
    echo "The admission check failed: $1. No package file was changed; $what changed. $outcome" >&2
    exit 1
  }
  # Any other exit (an unexpected error): only this attempt's own files go;
  # the state stays as it is, never opened.
  unexpected() {
    local code=$?
    [ "$failing" = false ] || return 0
    remove_temporaries
    remove_challenges
    local now="held"
    if state_is_open; then
      now="open"
    elif [ -n "$nonce" ] && state_is_hold "$nonce"; then
      now="held (this attempt's hold)"
    fi
    echo "admission.sh begin stopped unexpectedly (exit $code) before proving the hold. No package file was changed; the admission state is $now and stays so." >&2
  }
  trap unexpected EXIT

  # The challenge: the gate must answer for a script beside a .user.ini that
  # empties auto_prepend_file.
  challenge
  url="https://$ADMIN_HOST/gq-admission/$challenge/probe.php"
  probe "$challenge" || fail "$url didn't answer"
  [ "$ungated" = false ] \
    || fail "$url ran without the gate: the pool serving $ADMIN_HOST doesn't enforce php_admin_value[auto_prepend_file] = $GATE (a .user.ini, php_value or nothing at all isn't enough)"
  [ -n "$gate" ] || fail "$url answered ${status:-nothing} without the gate's headers"
  case "$user_ini" in
    - | .user.ini) ;;
    *)
      if [ "$user_ini" = . ] || [ "$user_ini" = .. ] || ! [[ "$user_ini" =~ ^[A-Za-z0-9._-]{1,64}$ ]] \
        || [ "$user_ini" = invalid ]; then
        fail "the pool's user_ini.filename is one gq can't challenge"
      fi
      # A custom user_ini.filename, challenged in a fresh directory.
      challenge_files=("$user_ini" .user.ini)
      challenge
      url="https://$ADMIN_HOST/gq-admission/$challenge/probe.php"
      probe "$challenge" || fail "$url didn't answer"
      [ "$ungated" = false ] && [ -n "$gate" ] \
        || fail "$url ran without the gate: the pool serving $ADMIN_HOST doesn't enforce php_admin_value[auto_prepend_file] = $GATE against $user_ini"
      ;;
  esac
  [[ "$php" =~ ^([0-9]+\.[0-9]+)\.[0-9] ]] || fail "$url reported a PHP version gq can't read ($php)"
  version="${BASH_REMATCH[1]}"
  fpm_master_visible "$version" \
    || fail "PHP-FPM $version's master process isn't visible to this user, so gq can't tell which workers serve $ADMIN_HOST or when the ones that ran before the hold have gone"
  [[ "$pid" =~ ^[0-9]+$ ]] || fail "$url reported no worker pid"
  pool="$(fpm_workers "$version" | awk -v pid="$pid" '$1 == pid { print $7 }')"
  [ -n "$pool" ] || fail "the worker $pid that answered isn't a worker of PHP-FPM $version's master"

  nonce="$(new_nonce)"
  write_atomically "$STATE" "held $nonce"$'\n'
  changed+=("the admission state (held)")
  old="$(fpm_workers "$version")"
  sudo -n service "php$version-fpm" reload >/dev/null \
    || fail "PHP-FPM $version couldn't be reloaded (sudo -n service php$version-fpm reload), so workers that ran before the hold may still serve"
  changed+=("a PHP-FPM $version reload")
  deadline=$((SECONDS + DRAIN_SECONDS))
  while :; do
    left="$(still_running "$old" | grep -c . || true)"
    [ "$left" = 0 ] && break
    [ "$SECONDS" -lt "$deadline" ] \
      || fail "$left PHP-FPM $version worker(s) that ran before the hold were still running after ${DRAIN_SECONDS}s"
    sleep 1
  done

  for attempt in $(seq 1 "$HELD_PROBES"); do
    probe "$challenge" || fail "$url didn't answer once held (probe $attempt)"
    [ "$ungated" = false ] || fail "$url ran without the gate after the reload"
    { [ "$status" = 503 ] && [ "$gate" = "$nonce" ]; } \
      || fail "$url answered $status without this hold's nonce"
    [[ "$php" == "$version."* ]] || fail "$url answered from PHP $php after the reload, not PHP-FPM $version"
    workers="$(fpm_workers "$version")"
    line="$(printf '%s\n' "$workers" | awk -v pid="$pid" '$1 == pid')"
    [ -n "$line" ] || fail "the worker $pid that answered after the reload isn't a worker of PHP-FPM $version's master"
    # Defence in depth: the drain already waited for every pre-reload
    # worker, so a worker from before it answering means ps disagrees with
    # itself.
    if printf '%s\n' "$old" | cut -d ' ' -f 1-6 | grep -qxF "$(printf '%s\n' "$line" | cut -d ' ' -f 1-6)"; then
      fail "the worker $pid that answered after the reload started before it"
    fi
    [ "${line##* }" = "$pool" ] \
      || fail "the worker $pid of pool ${line##* } answered, but the challenge was answered by pool $pool"
  done

  remove_challenges
  trap - EXIT
  echo "Held: the gate answered a nested override challenge, PHP-FPM $version (pool $pool) reloaded, every worker that ran before the hold has gone, and $HELD_PROBES requests to new workers of pool $pool answered 503 with this hold's nonce ($nonce)."
}

# Opens the Site: the end of a deploy that verified and finished every step.
lift() {
  check_paths
  trap 'remove_temporaries' EXIT
  write_atomically "$STATE" $'open\n'
  trap - EXIT
  echo "The hold is lifted: PHP requests are served again."
}

case "${1:-}" in
  prepare)
    trap 'remove_temporaries' EXIT
    prepare
    echo "The admission gate is $GATE${changed[*]:+ (written now)}; the admission state is unchanged ($(state_is_open && echo open || echo held)); no reload."
    ;;
  begin) begin ;;
  lift) lift ;;
  *) refuse "Usage: admission.sh prepare | begin | lift" ;;
esac
